int isa_fetch_decode(Decode *s) {
  int idx = EXEC_ID_inv;

#ifdef CONFIG_TDATA1_ICOUNT
  trig_action_t icount_action = check_triggers_icount(cpu.TM);
  trigger_handler(TRIG_TYPE_ICOUNT, icount_action, 0);
#endif // CONFIG_TDATA1_ICOUNT
#ifdef CONFIG_TDATA1_MCONTROL6
  if (trigger_mcontrol6_active(cpu.TM)) {
    trig_action_t mcontrol6_action = check_triggers_mcontrol6(cpu.TM, TRIG_OP_EXECUTE, s->pc, TRIGGER_NO_VALUE);
    trigger_handler(TRIG_TYPE_MCONTROL6, mcontrol6_action, s->pc);
  }
#endif // CONFIG_TDATA1_MCONTROL6

  s->isa.instr.val = instr_fetch(&s->snpc, 2);
  if (s->isa.instr.r.opcode1_0 != 0x3) {
    // this is an RVC instruction
    idx = table_rvc(s);
  }
  #ifdef CONFIG_CUSTOM_TENSOR
  else if (s->isa.instr.r.opcode6_2 == 0b01111) {
    // Not 32 bit. Here we only supports 64 bits
    uint32_t hi = instr_fetch(&s->snpc, 2);
    s->isa.instr.val |= (hi << 16);
    uint64_t val = instr_fetch(&s->snpc, 4);
    s->isa.instr.val |= (val << 32);
    idx = table_main_64(s);
  }
  #endif
  else {
    // this is a 4-byte instruction, should fetch the MSB part
    // NOTE: The fetch here may cause IPF.
    // If it is the case, we should have mepc = xxxffe and mtval = yyy000.
    // Refer to `mtval` in the privileged manual for more details.
    uint32_t hi = instr_fetch(&s->snpc, 2);
    s->isa.instr.val |= (hi << 16);
    idx = table_main(s);
  }

  s->type = INSTR_TYPE_N;
  switch (idx) {
    case EXEC_ID_c_j: case EXEC_ID_p_jal: case EXEC_ID_jal:
      s->jnpc = id_src1->imm; s->type = INSTR_TYPE_J; break;

    case EXEC_ID_beq: case EXEC_ID_bne: case EXEC_ID_blt: case EXEC_ID_bge:
    case EXEC_ID_bltu: case EXEC_ID_bgeu:
    case EXEC_ID_c_beqz: case EXEC_ID_c_bnez:
    case EXEC_ID_p_bltz: case EXEC_ID_p_bgez: case EXEC_ID_p_blez: case EXEC_ID_p_bgtz:
      s->jnpc = id_dest->imm; s->type = INSTR_TYPE_B; break;

    case EXEC_ID_p_ret: case EXEC_ID_c_jr: case EXEC_ID_c_jalr: case EXEC_ID_jalr:
    case EXEC_ID_c_ebreak:
    case EXEC_ID_mret: case EXEC_ID_sret: case EXEC_ID_ecall: case EXEC_ID_ebreak:
    IFDEF(CONFIG_RV_SMRNMI, case EXEC_ID_mnret:)
      s->type = INSTR_TYPE_I; break;
  }

  return idx;
}

