}

def_EHelper(vmvnr) {
  require_vector(true);
  check_vstart_exception(s);

  rtl_li(s, s1, s->isa.instr.v_opimm.v_imm5);
  // Reserved NREG encodings (imm5 not in {0,1,3,7}) must raise illegal (NEMU#1077).
  word_t imm5 = *s1;
  if (imm5 != 0 && imm5 != 1 && imm5 != 3 && imm5 != 7) {
    longjmp_exception(EX_II);
  }
  int NREG = (int)imm5 + 1;
  int len = (VLEN >> 6) * NREG;
  int vlmul = 0;
  while (NREG > 1) {
    NREG = NREG >> 1;
    vlmul++;
  }
  for (int i = 0; i < len; i++) {
    get_vreg(id_src2->reg, i, s0, 3, vlmul, 1, 1);
    set_vreg(id_dest->reg, i, *s0, 3, vlmul, 1);
  }
  vstart->val = 0;
  vp_set_dirty();
}

def_EHelper(vpopc) {
  require_vector(true);
  check_vstart_exception(s);

  rtl_li(s, s1, 0);
  for(word_t idx = vstart->val; idx < vl->val; idx ++) {
        // mask
    rtlreg_t mask = get_mask(0, idx);
    if(s->vm == 0 && mask == 0)
      continue;

    *s0 = get_mask(id_src2->reg, idx);
    *s0 &= 1;

    if(*s0 == 1)
      rtl_addi(s, s1, s1, 1);
  }
  rtl_sr(s, id_dest->reg, s1, 4);
  vstart->val = 0;
}

