  for (unsigned round = 0; round < 4; ++round) {
    for (unsigned train = 0; train < 16; ++train) {
      poison(); control_branch(out, a, b, 0);
      CHECK(result(0, dot(a,b)) || result(4, dot(a,b)), "branch training outputs");
