    CHECK(control_trap_value != 0xffffffffUL, "illegal mtval");
    for (unsigned i = 0; i < 12; ++i) CHECK(out[i] != 0xa5a5a5a5u, "younger destination/v0 preserved");
    CHECK(csr(0), "post trap CSR");
