    CHECK(result(0,expected) || csr(0), "128-step genuine v0 feedback chain");
  }
  for (unsigned i = 0; i < CONTROL_RANDOM_CASES; ++i) {
    for (unsigned j = 0; j < 16; ++j) { a[j] = byte(next()); b[j] = byte(next()); }
