def committed(text,windows):
    pattern=re.compile(r'\[\d{2}\] commit pc ([0-9a-f]+) inst ([0-9a-f]+) wen \d+ dst \d+ data ([0-9a-f]+) idx [0-9a-f]+[^\n]*\n')
