#ifndef VDOT_BENCH_RANDOM
#define VDOT_BENCH_RANDOM 1000
#endif
#ifndef VDOT_BENCH_FIRST
#define VDOT_BENCH_FIRST 0
#endif
#ifndef VDOT_BENCH_SMOKE
