extern void bench_compute(uint32_t *, const int8_t *, const int8_t *, uintptr_t, uintptr_t);
extern uintptr_t bench_kernel(uint32_t *, const int8_t *, const int8_t *, uintptr_t, uintptr_t, uintptr_t);
